<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Profile Cards</title>
    <style>
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            margin: 0;
            padding: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            background-color: #f4f4f4;
        }

        .profile-container {
            display: flex;
            flex-wrap: wrap;
            gap: 20px;
            max-width: 1200px;
            width: 100%;
        }

        .profile-card {
            flex: 1 1 300px;
            background-color: #fff;
            border-radius: 10px;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
            overflow: hidden;
            transition: transform 0.3s ease;
        }

        .profile-card:hover {
            transform: scale(1.05);
        }

        .avatar {
            width: 100%;
            height: 100px;
            background: linear-gradient(135deg, #ff6b6b, #fec7d2);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-size: 1.5rem;
            text-align: center;
            cursor: pointer;
        }

        .profile-card h2 {
            margin-top: 0;
            font-size: 1.2rem;
            color: #333;
        }

        .profile-card p {
            margin-top: 10px;
            font-size: 1rem;
            color: #666;
        }

        @media (max-width: 768px) {
            .profile-container {
                flex-direction: column;
            }
            .profile-card {
                flex: 1 1 100%;
            }
        }
    </style>
</head>
<body>

<div class="profile-container">
    <div class="profile-card">
        <img src="https://via.placeholder.com/100" alt="Avatar" class="avatar">
        <h2>Alice</h2>
        <p>Software Engineer</p>
        <p>Building scalable applications with a focus on user experience.</p>
    </div>
    <div class="profile-card">
        <img src="https://via.placeholder.com/100" alt="Avatar" class="avatar">
        <h2>Bob</h2>
        <p>Product Manager</p>
        <p>Overseeing the development of new features and user needs.</p>
    </div>
    <div class="profile-card">
        <img src="https://via.placeholder.com/100" alt="Avatar" class="avatar">
        <h2>Charlie</h2>
        <p>UX Designer</p>
        <p>Designing intuitive and beautiful interfaces for digital products.</p>
    </div>
</div>

</body>
</html>
